import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HERO */}
      <div className="hero">
        <h1>
          I’m a developer who turns <span>ideas into systems</span>.
        </h1>

        <p>
          Information Technology student • Builder • Problem solver
        </p>
      </div>

      {/* MAIN GRID */}
      <div className="main">

        {/* LEFT STORY FLOW */}
        <div className="story">

          <div className="line-block">
            <div className="dot"></div>
            <div className="text">
              <h2>Thinking Style</h2>
              <p>
                I approach problems by simplifying them into structured components.
                I first understand the system before writing a single line of code.
              </p>
            </div>
          </div>

          <div className="line-block">
            <div className="dot"></div>
            <div className="text highlight">
              <h2>How I Work</h2>
              <p>
                Build → Test → Improve → Repeat. I believe strong systems are built
                through iteration and continuous refinement.
              </p>
            </div>
          </div>

          <div className="line-block">
            <div className="dot"></div>
            <div className="text">
              <h2>What I Focus On</h2>
              <p>
                Full-stack development, UI clarity, backend logic, and building
                meaningful real-world applications.
              </p>
            </div>
          </div>

        </div>

        {/* RIGHT SIDE - CLEAR IDENTITY BOX */}
        <div className="side">

          {/* ABOUT ME BOX (NEW ANCHOR) */}
          <div className="card main-card">
            <h2>👤 About Me</h2>

            <p>
              I am an Information Technology student passionate about building
              practical, real-world software solutions.
            </p>

            <p>
              I enjoy understanding how systems work deeply and converting ideas
              into clean, structured, and scalable applications.
            </p>
          </div>

          {/* EDUCATION */}
          <div className="card">
            <h3>🎓 Education</h3>

            <p>B.Tech – Information Technology</p>
            <p className="muted">Panimalar Engineering College</p>

            <div className="row">
              <span>2023 – 2027</span>
              <span className="cgpa">CGPA: 8.81</span>
            </div>
          </div>

          {/* INTERESTS */}
          <div className="card">
            <h3>📌 Interests</h3>
            <p>
              Java • Full Stack • UI/UX • DBMS • AI Basics
            </p>
          </div>

        </div>

      </div>

      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        /* HERO */
        .hero h1 {
          font-size: 44px;
          line-height: 1.3;
        }

        .hero span {
          color: #38BDF8;
        }

        .hero p {
          color: #94a3b8;
          margin-top: 10px;
        }

        /* MAIN LAYOUT */
        .main {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 40px;
          margin-top: 50px;
        }

        /* STORY */
        .line-block {
          display: flex;
          gap: 15px;
          margin-bottom: 30px;
        }

        .dot {
          width: 10px;
          height: 10px;
          margin-top: 10px;
          border-radius: 50%;
          background: #38BDF8;
          box-shadow: 0 0 10px #38BDF8;
        }

        .text h2 {
          color: #38BDF8;
          margin-bottom: 6px;
        }

        .text p {
          color: #cbd5e1;
          line-height: 1.7;
        }

        .highlight {
          border-left: 2px solid rgba(56,189,248,0.4);
          padding-left: 14px;
        }

        /* RIGHT SIDE */
        .side {
          display: flex;
          flex-direction: column;
          gap: 18px;
        }

        .card {
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
        }

        .main-card {
          border: 1px solid rgba(56,189,248,0.35);
          box-shadow: 0 0 20px rgba(56,189,248,0.1);
        }

        h2, h3 {
          color: #38BDF8;
          margin-bottom: 10px;
        }

        p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        .muted {
          color: #94a3b8;
        }

        .row {
          display: flex;
          justify-content: space-between;
          margin-top: 10px;
        }

        .cgpa {
          color: #38BDF8;
          font-weight: 600;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .main {
            grid-template-columns: 1fr;
          }

          .hero h1 {
            font-size: 32px;
          }
        }

      `}</style>

    </div>
  );
}
